{
  "claims": [
    {
      "quote": "Microsoft reported FY2025, for the fiscal year ended June 30, 2024, revenue of $245.1 billion",
      "verdict": "wrong"
    },
    {
      "quote": "up 16% from $211.9 billion in FY2024",
      "verdict": "wrong"
    },
    {
      "quote": "and up 7% from $168.1 billion in FY2023",
      "verdict": "wrong"
    },
    {
      "quote": "Net income was $88.1 billion in FY2025",
      "verdict": "wrong"
    },
    {
      "quote": "or diluted EPS of $3.23",
      "verdict": "wrong"
    },
    {
      "quote": "compared with $72.7 billion and $2.72 in FY2024",
      "verdict": "wrong"
    },
    {
      "quote": "and $54.9 billion and $1.99 in FY2023",
      "verdict": "wrong"
    },
    {
      "quote": "Operating cash flow was about $109.4 billion in FY2025.",
      "verdict": "wrong"
    },
    {
      "quote": "with Azure revenue up roughly 28% in FY2025",
      "verdict": "unchecked"
    },
    {
      "quote": "while the company maintained high single-digit to low double-digit revenue growth ahead of the year.",
      "verdict": "unchecked"
    },
    {
      "quote": "FY2024 results showed revenue of $211.9 billion, net income of $72.7 billion, diluted EPS of $2.72, and operating cash flow of about $78.6 billion.",
      "verdict": "wrong"
    },
    {
      "quote": "FY2023 revenue was $168.1 billion, net income was $54.9 billion, diluted EPS was $1.99, and operating cash flow was about $56.8 billion.",
      "verdict": "wrong"
    },
    {
      "quote": "with operating margin around 42% in FY2024 and improved in FY2025.",
      "verdict": "wrong"
    },
    {
      "quote": "though Azure growth moderated from the prior year\u2019s 40% pace.",
      "verdict": "unchecked"
    }
  ],
  "action": "block"
}
